\begin{equation}
\label{reindex}
\prod_{q=1}^{p_{m+1}-p_{m}-M}\prod_{t=1}^{M-1}u^{i}_{(q+p_{m}-1 \ q+p_{m}-1+t)}(\Theta_{i_{m}}(x_{m})_{q,q}\Delta_{i_{m}}'(x_{m})_{q+t,q+t}).
\end{equation}
For each $1\leq q\leq p_{m+1}-p_{m}-M$ and $1\leq t\leq M-1$, note that 
$$
u^{i}_{(q+p_{m}-1 \ q+p_{m}-1+t)}=\operatorname{diag}(1_{p_{m}-1},u_{(q \ q+t)}^{i_{m}},1_{n_{i}^{j'}-p_{m+1}+1}).
$$
Hence, we may rewrite \autoref{reindex} as
$$
\begin{aligned}

\operatorname{diag}\left(1_{p_{m}-1},\prod_{q=1}^{p_{m+1}-p_{m}-M}u_{q}^{i_{m}}(x_{m}),1_{n_{i}^{j'}-p_{m+1}+1}\right)
=\operatorname{diag}\left(1_{p_{m}-1},W_{i_{m}}(x_{m}),1_{n_{i}^{j'}-p_{m+1}+1}\right).
\end{aligned}
$$
Therefore, for all $1\leq m <s$,
$$
\prod_{k=p_{m}}^{p_{m+1}-1}u_{k}^{i}(y)=\operatorname{diag}\left(1_{p_{m}-1},W_{i_{m}}(x_{m}),1_{n_{i}^{j'}-p_{m+1}+1}\right)
$$
and, similarly, 
$$
\prod_{k=p_{s}}^{n_{i}^{j'}-M}u_{k}^{i}(y)=\operatorname{diag}(1_{p_{s}-1},W_{i_{s}}(x_{s})).
$$
Plugging this into \autoref{Wi} shows that $W_{i}(y)=\operatorname{diag}(W_{i_{1}}(x_{1}),\ldots,W_{i_{s}}(x_{s}))$, which proves that $W\in A$. The proof of \autoref{far out} is now complete.

