V_{i}(y)&=W_{n_{i}}(\Theta_{i}(y)_{1,1},\ldots,\Theta_{i}(y)_{n_{i},n_{i}})\\	&=\operatorname{diag}\left(W_{n_{i_{1}}}(\Theta_{i_{1}}(x_{1})_{1,1},\ldots,\Theta_{i_{1}}(x_{1})_{n_{i_{1}},n_{i_{1}}}),\ldots,W_{i_{s}}(\Theta_{i_{s}}(x_{s})_{1,1},\ldots,\Theta_{i_{s}}(x_{s})_{n_{i_{s}},n_{i_{s}}})\right)\\	&=\operatorname{diag}(V_{i_{1}}(x_{1}),\ldots,V_{i_{s}}(x_{s})).
\end{aligned}
$$
Therefore, $V\in A$. This completes the proof of \autoref{lower triangular}.

