\label{Toms-Winter}
Let $A$ be a separable, unital, simple, non-elementary, nuclear $\mathrm{C}^{*}$-algebra. The following statements are equivalent.
\begin{enumerate}
	\item $A$ has finite nuclear dimension.
	\item $A$ is $\mathcal{Z}$-stable; that is, $A\otimes \mathcal{Z}\cong A$.
	\item $A$ has strict comparison of positive elements. 
\end{enumerate}

\label{returning}
Suppose $R\subset S\subset T$. Let $1\leq i\leq  l (R)$ and $x\in X_{i}^{R}\setminus Y_{i}^{R}=\lambda_{R}^{-1}(n_{i}^{R})$. Then, there are indices $1\leq i_{1},\ldots,i_{q}\leq  l (S)$ such that:
\begin{enumerate}
	\item $n_{i_{1}}^{S}+\cdots+n_{i_{q}}^{S}=n_{i}^{R}$;
	\item for all $1\leq k\leq n_{i}^{R}$, $h^{k}(x)\in S$ if and only if $k=n_{i_{1}}^{S}+\cdots+n_{i_{j}}^{S}$ for some $1\leq j\leq q$;
	\item $x\in X_{i_{1}}^{S}\setminus Y_{i_{1}}^{S}$ and, for all $2\leq j\leq q$, $h^{n_{i_{1}}^{S}+\cdots+n_{i_{j-1}}^{S}}(x)\in X_{i_{j}}^{S}\setminus Y_{i_{j}}^{S}$.
\end{enumerate}

\begin{equation}
	\label{function identification}
	\gamma_{S}(f)_{i}=\operatorname{diag}\left(f\circ h|_{X_{i}^{S}},f\circ h^{2}|_{X_{i}^{S}},\ldots,f\circ h^{n_{i}^{S}}|_{X_{i}^{S}}\right)
\end{equation}

\begin{equation}
