	\item $n_{i_{1}}^{S}+\cdots+n_{i_{q}}^{S}=n_{i}^{R}$;
	\item for all $1\leq k\leq n_{i}^{R}$, $h^{k}(x)\in S$ if and only if $k=\beta_{j}$ for some $1\leq j\leq q$, where $\beta_{j}:=n_{i_{1}}^{S}+\cdots+n_{i_{j}}^{S}$;
	\item for all $1\leq j\leq q$, $h^{\beta_{j-1}}(x)\in X_{i_{j}}^{S}\setminus Y_{i_{j}}^{S}$ (here $\beta_{0}:=0$, so that $x\in X_{i_{1}}^{S}\setminus Y_{i_{1}}^{S}$).
\end{enumerate}	
Let us show that $x$ decomposes into $h^{\beta_{0}}(x)=x,h^{\beta_{1}}(x),\ldots,h^{\beta_{q-1}}(x)$ under $\psi$. 

Suppose that $f\in C(T)$. Let us begin by verifying that
\begin{equation}
	\label{diagonal f}
	\begin{aligned}
