	\end{aligned}
\end{equation}
Fix $1\leq j\leq q$. By \autoref{function identification},  
$$
\begin{aligned}
\gamma_{S}(f)_{i_{j}}(h^{\beta_{j-1}}(x))&=\operatorname{diag}\left(f(h(h^{\beta_{j-1}}(x))),\ldots,f(h^{n_{i_{j}}^{S}}(h^{\beta_{j-1}}(x)))\right)\\
&=\operatorname{diag}\left(f(h^{\beta_{j-1}+1}(x)),\ldots,f(h^{\beta_{j}}(x))\right).
\end{aligned}
$$
Hence, 
$$
\begin{aligned}
&\operatorname{diag}\left(\gamma_{S}(f)_{i_{1}}(x),\gamma_{S}(f)_{i_{2}}(h^{\beta_{1}}(x)),\ldots,\gamma_{S}(f)_{i_{q}}(h^{\beta_{q-1}}(x))\right)\\
=&\operatorname{diag}\left(f(h^{\beta_{0}+1}(x)),\ldots,f(h^{\beta_{1}}(x)),\ldots\ldots,f(h^{\beta_{q-1}+1}(x)),\ldots,f(h^{\beta_{q}}(x))\right)\\
=&\operatorname{diag}\left(f(h(x)),\ldots,f(h^{n_{i}^{R}}(x))\right)\\
=&\gamma_{R}(f)_{i}(x),
\end{aligned}
$$
which yields \autoref{diagonal f}.

Next, suppose $g\in C_{0}(T\setminus S)$. Let us show that 
\begin{equation}
